Consider the following C program.
<pre><code> #include &lt;stdio.h&gt;
#include &lt;string.h&gt;
void printlength (char *s, char *t) {
 unsigned int c = 0;
 int len = ((strlen(s) - strlen (t)) > c) ? strlen(s): strlen(t);
 printf ("%d\n", len);
}
void main ( ) {
 char *x = "abc";
 char *y ="defgh"; 
 printlength (x,y);
}</code></pre>
Recall that strlen is defined in string.h as returning a value of type size_t, which is an
unsigned int. The output of the program is _____________.

The output of executing the following C program is ________.
<pre><code> #include &lt;stdio.h&gt;
int total (int v) {
    static int count = 0;
    while (v) {
        count += v &amp; 1;
        v >>= 1;
    }
    return count;
 }
void main ( ) {
static int x = 0;
int i = 5;
for (; i> 0; i--) {
x=x + total (i) ; 
}
printf ("%d\n", x) ; } </code></pre>
